INSERT INTO spells (id, name, level, school, casting_time, range, area, components, duration, concentration, ritual, classes, description, higher_levels, img_url, created_at, updated_at) VALUES
(1, 'Acid Splash', '0', 'Evocation', 'Action', '60 ft', NULL, 'V,S', 'Instantaneous', 0, 0, NULL, 'You hurl a bubble of acid. Choose one or two creatures you can see within range. If you choose two, they must be within 5 feet of each other. A target must succeed on a Dexterity saving throw or take 1d6 acid damage.', NULL, NULL, NULL, NULL),
(2, 'Aid', '2', 'Abjuration', 'Action', '30 ft', NULL, 'V,S,M', '8 hours', 0, 0, NULL, 'Your spell bolsters your allies with toughness and resolve. Choose up to three creatures within range. Each target''s hit point maximum and current hit points increase by 5 for the duration.', NULL, NULL, NULL, NULL),
(3, 'Alarm', '1', 'Abjuration', '1 minute or Ritual', '30 ft', NULL, 'V,S,M', '8 hours', 0, 1, NULL, 'You set an alarm against unwanted intrusion. Choose a door, a window, or an area within range that is no larger than a 20-foot cube. Until the spell ends, an alarm alerts you whenever a Tiny or larger creature touches or enters the warded area.', NULL, NULL, NULL, NULL),
(4, 'Alter Self', '2', 'Transmutation', 'Action', 'Self', NULL, 'V,S', '1 hour', 1, 0, NULL, 'You assume a different form. When you cast the spell, choose one of the following options, the effects of which last for the duration of the spell.', NULL, NULL, NULL, NULL),
(5, 'Animal Friendship', '1', 'Enchantment', 'Action', '30 ft', NULL, 'V,S,M', '24 hours', 0, 0, NULL, 'This spell lets you convince a beast that you mean it no harm. Choose a beast that you can see within range. It must see and hear you. If the beast''s Intelligence is 4 or higher, the spell fails.', NULL, NULL, NULL, NULL),
(6, 'Animal Messenger', '2', 'Enchantment', 'Action or Ritual', '30 ft', NULL, 'V,S,M', '24 hours', 0, 1, NULL, 'By means of this spell, you use an animal to deliver a message. Choose a Tiny beast you can see within range, such as a squirrel, a blue jay, or a bat.', NULL, NULL, NULL, NULL),
(7, 'Animal Shapes', '8', 'Transmutation', 'Action', '30 ft', NULL, 'V,S', '24 hours', 0, 0, NULL, 'Your magic turns others into beasts. Choose any number of willing creatures that you can see within range. You transform each target into the form of a Large or smaller beast with a challenge rating of 4 or lower.', NULL, NULL, NULL, NULL),
(8, 'Animate Dead', '3', 'Necromancy', '1 minute', '10 ft', NULL, 'V,S,M', 'Instantaneous', 0, 0, NULL, 'This spell creates an undead servant. Choose a pile of bones or a corpse of a Medium or Small humanoid within range. Your spell imbues the target with a foul mimicry of life, raising it as an undead creature.', NULL, NULL, NULL, NULL),
(9, 'Animate Objects', '5', 'Transmutation', 'Action', '120 ft', NULL, 'V,S', '1 minute', 1, 0, NULL, 'Objects come to life at your command. Choose up to ten nonmagical objects within range that are not being worn or carried. Medium targets count as two objects, Large targets count as four objects, Huge targets count as eight objects.', NULL, NULL, NULL, NULL),
(10, 'Antilife Shell', '5', 'Abjuration', 'Action', 'Self', NULL, 'V,S', '1 hour', 1, 0, NULL, 'A shimmering barrier extends out from you in a 10-foot radius and moves with you, remaining centered on you and hedging out creatures other than undead and constructs.', NULL, NULL, NULL, NULL),
(11, 'Antimagic Field', '8', 'Abjuration', 'Action', 'Self', NULL, 'V,S,M', '1 hour', 1, 0, NULL, NULL, NULL, 'https://www.aidedd.org/spell/antimagic-field', NULL, NULL),
